import React, { useState, useRef, useCallback } from 'react';
import { getById, CATEGORIES } from '../registry';
import './AlgoPage.css';

const SPEED_MAP    = { 1: 800, 2: 400, 3: 150, 4: 50, 5: 8 };
const SPEED_LABELS = { 1: 'Slow', 2: 'Moderate', 3: 'Medium', 4: 'Fast', 5: 'Instant' };

const DIFFICULTY_COLOR = {
  beginner:     'var(--diff-beginner)',
  intermediate: 'var(--diff-intermediate)',
  advanced:     'var(--diff-advanced)',
};

export default function AlgoPage({ algoId, onBack }) {
  const meta = getById(algoId);

  // Animation state
  const [steps, setSteps]           = useState([]);
  const [stepIdx, setStepIdx]       = useState(0);
  const [isRunning, setIsRunning]   = useState(false);
  const [isPaused, setIsPaused]     = useState(false);
  const [currentStep, setCurrentStep] = useState(null);
  const [speed, setSpeed]           = useState(3);
  const [log, setLog]               = useState('Press Run to start.');
  const [stats, setStats]           = useState({ comparisons: 0, swaps: 0, steps: 0 });

  const timerRef   = useRef(null);
  const speedRef   = useRef(3);
  const stepsRef   = useRef([]);
  const idxRef     = useRef(0);
  const statsRef   = useRef({ comparisons: 0, swaps: 0, steps: 0 });

  // ---- Animation engine ----
  const tick = useCallback(() => {
    const s = stepsRef.current;
    const i = idxRef.current;
    if (i >= s.length) {
      setIsRunning(false); setIsPaused(false);
      return;
    }
    const step = s[i];
    idxRef.current = i + 1;

    const st = statsRef.current;
    st.steps++;
    if (step.type === 'compare') st.comparisons++;
    if (step.type === 'swap')    st.swaps++;
    statsRef.current = { ...st };

    setCurrentStep(step);
    setStepIdx(i + 1);
    setStats({ ...st });
    setLog(step.msg || '');

    if (step.done) { setIsRunning(false); setIsPaused(false); return; }
    timerRef.current = setTimeout(tick, SPEED_MAP[speedRef.current] || 150);
  }, []);

  const runSteps = useCallback((newSteps) => {
    clearTimeout(timerRef.current);
    stepsRef.current = newSteps;
    idxRef.current   = 0;
    statsRef.current = { comparisons: 0, swaps: 0, steps: 0 };
    setSteps(newSteps);
    setStepIdx(0);
    setStats({ comparisons: 0, swaps: 0, steps: 0 });
    setIsRunning(true);
    setIsPaused(false);
    tick();
  }, [tick]);

  const handlePause = () => {
    clearTimeout(timerRef.current);
    setIsRunning(false); setIsPaused(true);
  };

  const handleResume = () => {
    setIsRunning(true); setIsPaused(false);
    tick();
  };

  const handleReset = useCallback(() => {
    clearTimeout(timerRef.current);
    stepsRef.current = [];
    idxRef.current   = 0;
    statsRef.current = { comparisons: 0, swaps: 0, steps: 0 };
    setSteps([]); setStepIdx(0); setCurrentStep(null);
    setIsRunning(false); setIsPaused(false);
    setStats({ comparisons: 0, swaps: 0, steps: 0 });
    setLog('Reset. Press Run to start.');
  }, []);

  const handleSpeedChange = (e) => {
    const s = parseInt(e.target.value);
    setSpeed(s); speedRef.current = s;
  };

  if (!meta) {
    return (
      <div className="algo-page-error">
        <p>Algorithm "{algoId}" not found.</p>
        <button onClick={onBack}>← Back</button>
      </div>
    );
  }

  const cat = CATEGORIES.find(c => c.id === meta.category);

  // Lazy-load the visualizer for this algo
  const VisualizerModule = React.lazy(() =>
    import(`../algos/${meta.category}/${meta.id}/Visualizer.jsx`)
  );

  const btnLabel = isRunning ? 'Pause' : isPaused ? 'Resume' : 'Run';
  const handleRunBtn = () => {
    if (isRunning)  { handlePause();  return; }
    if (isPaused)   { handleResume(); return; }
    // signal the visualizer to start — it calls runSteps
  };

  return (
    <div className="algo-page">

      {/* ---- Page header ---- */}
      <div className="algo-page-header">
        <button className="back-btn" onClick={onBack}>← Back</button>

        <div className="algo-page-title-area">
          <span className="algo-page-emoji">{meta.emoji}</span>
          <div>
            <h1 className="algo-page-title">{meta.label}</h1>
            <div className="algo-page-tags">
              {cat && <span className="tag" style={{ color: cat.color, borderColor: cat.color + '44' }}>{cat.label}</span>}
              <span className="tag" style={{ color: DIFFICULTY_COLOR[meta.difficulty], borderColor: DIFFICULTY_COLOR[meta.difficulty] + '44' }}>
                {meta.difficulty}
              </span>
              <span className="tag">{meta.timeComplexity.average}</span>
              <span className="tag">space {meta.spaceComplexity}</span>
              {meta.stable !== null && <span className="tag">{meta.stable ? 'stable' : 'unstable'}</span>}
            </div>
          </div>
        </div>
      </div>

      {/* ---- Visualization area ---- */}
      <div className="viz-area">
        <React.Suspense fallback={<div className="viz-loading">Loading visualizer...</div>}>
          <VisualizerModule
            isRunning={isRunning}
            isPaused={isPaused}
            currentStep={currentStep}
            stepIdx={stepIdx}
            onRunSteps={runSteps}
            onReset={handleReset}
            speed={speed}
          />
        </React.Suspense>
      </div>

      {/* ---- Controls ---- */}
      <div className="algo-controls">
        <div className="controls-left">
          <button
            className={`ctrl-btn ctrl-run ${isRunning ? 'pausing' : ''}`}
            onClick={handleRunBtn}
            disabled={steps.length > 0 && !isRunning && !isPaused && stepIdx === steps.length}
          >
            {btnLabel}
          </button>
          <button className="ctrl-btn ctrl-reset" onClick={handleReset} disabled={isRunning}>
            ↺ Reset
          </button>
        </div>

        <div className="controls-right">
          <div className="speed-control">
            <span className="ctrl-label">Speed</span>
            <input type="range" min="1" max="5" step="1" value={speed} onChange={handleSpeedChange} />
            <span className="speed-label">{SPEED_LABELS[speed]}</span>
          </div>
        </div>
      </div>

      {/* ---- Step log ---- */}
      <div className="step-log">
        <span className="step-log-label">step {stepIdx}</span>
        <span className="step-log-msg">{log}</span>
      </div>

      {/* ---- Stats row ---- */}
      <div className="stats-row">
        <div className="stat-item">
          <span className="stat-val">{stats.comparisons}</span>
          <span className="stat-label">Comparisons</span>
        </div>
        <div className="stat-item">
          <span className="stat-val">{stats.swaps}</span>
          <span className="stat-label">Swaps</span>
        </div>
        <div className="stat-item">
          <span className="stat-val">{stats.steps}</span>
          <span className="stat-label">Total Steps</span>
        </div>
      </div>

      {/* ---- Description + Key insight ---- */}
      <div className="algo-info-panels">
        <div className="info-panel">
          <div className="info-panel-title">What it does</div>
          <p className="info-panel-body">{meta.description}</p>
        </div>
        <div className="info-panel info-panel-accent" style={{ '--accent': cat?.color || 'var(--blue)' }}>
          <div className="info-panel-title">Key insight</div>
          <p className="info-panel-body">{meta.keyInsight}</p>
        </div>
        <div className="info-panel">
          <div className="info-panel-title">Use cases</div>
          <ul className="use-cases-list">
            {meta.useCases.map(u => <li key={u}>{u}</li>)}
          </ul>
        </div>
      </div>

      {/* ---- Complexity table ---- */}
      <div className="complexity-panel">
        <div className="complexity-title">Complexity</div>
        <div className="complexity-grid">
          {[
            ['Best Case',    meta.timeComplexity.best,    'time'],
            ['Average Case', meta.timeComplexity.average, 'time'],
            ['Worst Case',   meta.timeComplexity.worst,   'time'],
            ['Space',        meta.spaceComplexity,        'space'],
          ].map(([label, val, type]) => (
            <div key={label} className="complexity-cell">
              <span className="complexity-label">{label}</span>
              <span className={`complexity-val ${
                val.includes('n²') || val.includes('n²') ? 'bad' :
                val === 'O(1)' || val.includes('log') ? 'good' : 'ok'
              }`}>{val}</span>
            </div>
          ))}
          {meta.stable !== null && (
            <div className="complexity-cell">
              <span className="complexity-label">Stable</span>
              <span className={`complexity-val ${meta.stable ? 'good' : 'bad'}`}>{meta.stable ? 'Yes' : 'No'}</span>
            </div>
          )}
        </div>
      </div>

    </div>
  );
}
